TimeIndependentJump<1> mode::aDagJump(double fact)
{
  return [=] (StateVectorView<1> psi) {
    for (size_t n=psi.extents[0]-1; n>0; --n) psi(n)=fact*sqrt(n)*psi(n-1);
    psi(0)=0;
  };
