  return {
    .label{"photon loss"},
    .jump{aJump(sqrt(fact))},
    .rate{ [=] (StateVectorConstView<1> psi) {return fact*photonnumber(psi);} },
    .superoperator{aSuperoperator(sqrt(fact))}
