    .jump{aDagJump(sqrt(fact))},
    .rate{ [=] (StateVectorConstView<1> psi) {
      double res=0;
      for (size_t n=0; n<psi.extents[0]; ++n) res+=(n+1)*sqrAbs(psi(n));
      return fact*res;
    }},
    .superoperator{aDagSuperoperator(sqrt(fact))}
  };
